/* part:page.script.preview.kit.rich-text */
/* The catalog's live preview of kit.rich-text. It rides with the kit and only the catalog page loads it: `adp.py take` leaves it out. */
(function () {
'use strict';
const { html, useState, useEffect, useRef } = window.htmPreact;
const P = window.CatalogPreviews = window.CatalogPreviews || {};
const K = () => window.Kit;
const first = (samples, part) => samples[Object.keys(samples).find(k => k.endsWith('/' + part + '.json'))];
const Sim = ({ children }) => html`<p class="pv-sim"><b>Sandbox</b> ${children}</p>`;
const CSS = `.pv-rt-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:14px;align-items:start;min-width:0}
.pv-rt-grid[data-stack]{grid-template-columns:minmax(0,1fr)}
.pv-rt-frame{width:100%;min-width:0;box-sizing:border-box}
.pv-rt-out{display:grid;gap:8px;min-width:0}
.pv-rt-code{margin:0;max-height:440px;overflow:auto;padding:10px 12px;border:1px solid var(--rule);border-radius:8px;background:var(--sunk);color:var(--ink);font:12px/1.55 var(--f-mono);white-space:pre-wrap;overflow-wrap:anywhere}
.pv-rt-log{margin:0;padding:7px 10px;border-radius:6px;background:var(--sunk);font:12px/1.5 var(--f-mono);color:var(--ink-2);overflow-wrap:anywhere}
.pv-rt-dirty summary{cursor:pointer;font:600 13px var(--f-ui);color:var(--ink-2)}
.pv-rt-dirty pre{margin:6px 0 0;max-height:180px;overflow:auto;padding:8px 10px;border-radius:6px;background:var(--sunk);font:11.5px/1.5 var(--f-mono);white-space:pre-wrap;overflow-wrap:anywhere;color:var(--ink-2)}`;

P['kit.rich-text'] = ({ samples }) => {
  const d = first(samples, 'rich-text');
  const [key, setKey] = useState(d.samples[0].key);
  const [w, setW] = useState('full');
  const [view, setView] = useState('html');
  const [out, setOut] = useState({ html: '', md: '', text: '' });
  const [st, setSt] = useState(null);
  const [sel, setSel] = useState(null);
  const [rep, setRep] = useState(null);
  const [ro, setRo] = useState(false);
  const s = d.samples.find(x => x.key === key) || d.samples[0];
  const host = useRef(null), h = useRef(null);
  const pull = () => { const x = h.current; if (x) setOut({ html: x.getHTML(), md: x.getMarkdown(), text: x.getText() }); };
  useEffect(() => {
    const o = Object.assign({}, s.opts);
    if (s.dirty) o.value = s.dirty;
    setRep(null); setSel(null); setRo(!!o.readOnly);
    h.current = K().richText.mount(host.current, Object.assign(o, {
      onChange: x => { setSt(x); pull(); },
      onSelection: x => setSel(x),
      onPaste: r => { setRep(r); }
    }));
    setSt(h.current.get()); pull();
    return () => { h.current.destroy(); h.current = null; };
  }, [key]);
  const width = s.width ? s.width + 'px' : w === 'phone' ? '360px' : '100%';
  const stack = !!s.width || w === 'phone';
  const pick = (v, set, cur) => html`<button type="button" key=${v[0]} class=${'pv-btn' + (v[0] === cur ? ' pri' : '')} aria-pressed=${v[0] === cur} onClick=${() => set(v[0])}>${v[1]}</button>`;
  const shown = view === 'html' ? out.html : view === 'md' ? out.md : out.text;
  const marks = sel ? Object.keys(sel.marks).filter(k => sel.marks[k]).join('+') || 'none' : '';
  return html`<div class="pv-stack"><style>${CSS}</style>
    <div class="pv-row" role="group" aria-label="Sample"><span class="pv-label">Sample</span>${d.samples.map(x => pick([x.key, x.label], setKey, key))}</div>
    ${!s.width && html`<div class="pv-row" role="group" aria-label="Frame width"><span class="pv-label">Frame</span>${[['full', 'Full width'], ['phone', '360 px']].map(x => pick(x, setW, w))}</div>`}
    <${Sim}>${s.about}${ro ? '' : ' Try the typing rules (# , - , 1. , > , ```, **bold**), Ctrl+K for a link, Tab and Shift+Tab in a list, Alt+F10 for the toolbar.'} The editor keeps nothing: the page decides what to keep from onChange.<//>
    ${s.dirty && html`<div class="pv-stack" style="gap:8px">
      <details class="pv-rt-dirty"><summary>The dirty HTML this sample starts from</summary><pre>${s.dirty}</pre></details>
      <div class="pv-row"><button type="button" class="pv-btn pri" onClick=${() => { h.current && h.current.insertHTML(s.dirty); pull(); }}>Paste the dirty HTML at the caret</button>
        <button type="button" class="pv-btn" onClick=${() => { h.current && h.current.setHTML(s.dirty); setRep(null); pull(); }}>Load it as the value</button></div>
      ${rep && html`<p class="pv-rt-log" aria-live="polite">onPaste removed ${Object.entries(rep.removed).map(([k, v]) => v + ' ' + k).join(', ') || 'no elements'}; ${rep.attributes} attributes stripped; ${rep.links} safe links kept</p>`}
    </div>`}
    <div class="pv-rt-grid" data-stack=${stack || null}>
      <div class="pv-rt-frame" style=${'max-width:' + width} dir=${s.dir || null} lang=${(s.opts && s.opts.locale) || null}><div ref=${host}></div></div>
      <div class="pv-rt-out">
        <div class="pv-row" role="group" aria-label="Output"><span class="pv-label">Output</span>${[['html', 'HTML'], ['md', 'Markdown'], ['text', 'Text']].map(x => pick(x, setView, view))}
          <button type="button" class=${'pv-btn' + (ro ? ' pri' : '')} aria-pressed=${ro} onClick=${() => { const v = !ro; setRo(v); h.current && h.current.update({ readOnly: v }); }}>Read-only</button></div>
        <pre class="pv-rt-code" aria-label=${'Live ' + view + ' output'} tabindex="0">${shown || '(empty)'}</pre>
      </div>
    </div>
    <p class="pv-rt-log" aria-live="off">onChange ${st ? JSON.stringify({ words: st.words, chars: st.chars, over: st.over, max: st.max }) : 'no change yet'}${sel ? ' · onSelection ' + JSON.stringify({ block: sel.block, list: sel.list, quote: sel.quote, marks, link: sel.link }) : ''}</p>
  </div>`;
};
})();
/* /part:page.script.preview.kit.rich-text */

/* part:page.style.kit.rich-text */
/* Kit css: rich text editor    kit version 1.0.0    pairs with kit/rich-text.js
   .kit-rt (the host; a size container; [data-over] [data-readonly] [data-scrolls]), .kit-rt-box (the frame), .kit-rt-bar (role toolbar; sticky, scrolls sideways when narrow),
   .kit-rt-btn[aria-pressed|aria-disabled|aria-expanded] (toolbar buttons; .kit-rt-blockbtn the text-style menu button), .kit-rt-sep, .kit-rt-menu / .kit-rt-mi (menuitemradio),
   .kit-rt-ed (the contenteditable text; [data-empty] shows data-placeholder), .kit-rt-foot (.kit-rt-count, .kit-rt-limit[data-state=near|over] with a ! mark, .kit-rt-ro),
   .kit-rt-pop (link dialog: .kit-rt-in, .kit-rt-err, .kit-rt-pb), .kit-rt-tip (shortcut tooltip), .kit-rt-sr (announcements).
   A pressed button has a tinted ground and a bar under its icon, not colour alone; an over-limit editor gets a thicker border and a "!" mark beside the words.
   Needs from the board: --panel --sunk --ink --ink-2 --ink-3 --rule --rule-2 --accent --accent-ink --accent-soft --danger --danger-soft --warn --warn-soft --shadow
   --f-ui --f-display --f-mono --text-size --leading --head-case; optional --focus (the focus ring), --rt-radius (corners, default 10px),
   --rt-sticky-top (toolbar offset when the page scrolls, default 0), --rt-pad (text padding, default 14px 16px). */
.kit-rt { container-type: inline-size; position: relative; min-width: 0; color: var(--ink); font: var(--text-size, 15px)/var(--leading, 1.55) var(--f-ui); }
.kit-rt-box { position: relative; display: flex; flex-direction: column; min-width: 0; border: 1px solid var(--rule); border-radius: var(--rt-radius, 10px); background: var(--panel); }
.kit-rt-box:focus-within { border-color: var(--focus, var(--accent)); box-shadow: 0 0 0 3px var(--accent-soft); }
.kit-rt[data-over] .kit-rt-box { border-color: var(--danger); border-width: 2px; }

/* toolbar: one row; it scrolls sideways rather than wrapping, and sticks to the top of a scrolling page */
.kit-rt-bar { position: sticky; top: var(--rt-sticky-top, 0); z-index: 2; display: flex; align-items: center; gap: 2px; min-width: 0; padding: 4px 6px; border-bottom: 1px solid var(--rule); border-radius: var(--rt-radius, 10px) var(--rt-radius, 10px) 0 0; overflow-x: auto;
  /* scroll shadows: a soft edge shows on the side where more buttons wait, and only there */
  background: linear-gradient(to right, var(--panel) 40%, transparent) left / 28px 100% no-repeat local, linear-gradient(to left, var(--panel) 40%, transparent) right / 28px 100% no-repeat local,
    linear-gradient(to right, color-mix(in srgb, var(--ink) 18%, transparent), transparent) left / 12px 100% no-repeat scroll, linear-gradient(to left, color-mix(in srgb, var(--ink) 18%, transparent), transparent) right / 12px 100% no-repeat scroll, var(--panel); overscroll-behavior-x: contain; scrollbar-width: thin; }
.kit-rt-bar[hidden] { display: none; }
.kit-rt-btn { flex: 0 0 auto; position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 4px; min-width: 34px; height: 34px; padding: 0 7px; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--ink-2); font: 600 13px/1 var(--f-ui); cursor: pointer; }
.kit-rt-btn svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.kit-rt-btn[data-cmd="bold"] svg { stroke-width: 2.4; }
.kit-rt-btn[data-cmd="bulletList"] svg, .kit-rt-btn[data-cmd="orderedList"] svg { stroke-width: 1.8; }
.kit-rt-btn:hover { background: var(--sunk); color: var(--ink); }
.kit-rt-btn:focus-visible { outline: 2px solid var(--focus, var(--accent)); outline-offset: -2px; }
.kit-rt-btn[aria-pressed="true"] { background: var(--accent-soft); color: var(--ink); border-color: color-mix(in srgb, var(--accent) 45%, transparent); }
.kit-rt-btn[aria-pressed="true"]::after { content: ""; position: absolute; inset-inline: 8px; bottom: 3px; height: 2px; border-radius: 2px; background: var(--accent); }
.kit-rt-btn[aria-disabled="true"] { opacity: .4; cursor: default; }
.kit-rt-btn[aria-disabled="true"]:hover { background: transparent; color: var(--ink-2); }
.kit-rt-blockbtn { min-width: 9.5em; justify-content: space-between; padding-inline: 10px 6px; border-color: var(--rule); color: var(--ink); font-weight: 500; }
.kit-rt-blockbtn svg { width: 16px; height: 16px; }
.kit-rt-blockbtn[aria-expanded="true"] { background: var(--sunk); }
.kit-rt-bl { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 12em; line-height: 1.35; }
.kit-rt-sep { flex: 0 0 auto; width: 1px; height: 20px; margin: 0 4px; background: var(--rule); }
.kit-rt-flip:dir(rtl) svg { transform: scaleX(-1); }

/* the text */
.kit-rt-ed { position: relative; flex: 1 1 auto; min-width: 0; min-height: 6em; padding: var(--rt-pad, 14px 16px); outline: none; overflow-wrap: anywhere; overflow-y: auto; color: var(--ink); caret-color: var(--accent); }
.kit-rt-ed[data-empty][data-placeholder]::before { content: attr(data-placeholder); position: absolute; inset-inline: 0; padding: var(--rt-pad, 14px 16px); padding-top: inherit; top: 0; color: var(--ink-3); pointer-events: none; white-space: pre-wrap; }
.kit-rt[data-readonly] .kit-rt-ed { caret-color: transparent; }
.kit-rt[data-readonly] .kit-rt-box:focus-within { box-shadow: none; }
.kit-rt[data-readonly] .kit-rt-ed:focus-visible { outline: 2px solid var(--focus, var(--accent)); outline-offset: -3px; border-radius: var(--rt-radius, 10px); }
.kit-rt-ed > :first-child { margin-top: 0; }
.kit-rt-ed > :last-child { margin-bottom: 0; }
.kit-rt-ed p { margin: 0 0 .7em; }
.kit-rt-ed h2, .kit-rt-ed h3 { margin: 1.1em 0 .45em; font-family: var(--f-display, var(--f-ui)); text-transform: var(--head-case, none); line-height: 1.25; color: var(--ink); }
.kit-rt-ed h2 { font-size: 1.4em; font-weight: 700; }
.kit-rt-ed h3 { font-size: 1.15em; font-weight: 650; }
.kit-rt-ed ul, .kit-rt-ed ol { margin: 0 0 .7em; padding-inline-start: 1.6em; }
.kit-rt-ed li { margin: .15em 0; padding-inline-start: .15em; }
.kit-rt-ed li > ul, .kit-rt-ed li > ol { margin: .15em 0 .2em; }
.kit-rt-ed ul ul { list-style-type: circle; }
.kit-rt-ed ul ul ul { list-style-type: square; }
.kit-rt-ed ol ol { list-style-type: lower-alpha; }
.kit-rt-ed ol ol ol { list-style-type: lower-roman; }
.kit-rt-ed blockquote { margin: 0 0 .7em; padding: .1em 0 .1em 1em; padding-inline: 1em 0; border-inline-start: 3px solid var(--rule); color: var(--ink-2); }
.kit-rt-ed blockquote > :last-child { margin-bottom: 0; }
.kit-rt-ed pre { margin: 0 0 .7em; padding: 10px 12px; border-radius: 8px; border: 1px solid var(--rule-2); background: var(--sunk); color: var(--ink); font: .88em/1.5 var(--f-mono); white-space: pre-wrap; overflow-wrap: anywhere; text-align: left; tab-size: 4; }
.kit-rt-ed code { padding: .08em .32em; border-radius: 4px; background: var(--sunk); font: .9em var(--f-mono); }
.kit-rt-ed a { color: var(--accent); text-decoration: underline; text-underline-offset: .18em; text-decoration-thickness: 1px; }
.kit-rt-ed hr { height: 0; margin: 1.1em 0; border: 0; border-top: 2px solid var(--rule); }
.kit-rt-ed img { max-width: 100%; height: auto; vertical-align: middle; }
.kit-rt-ed s { text-decoration-thickness: 1.5px; }
.kit-rt-ed u { text-underline-offset: .15em; }
::highlight(kit-rt-target) { background-color: var(--accent-soft); color: var(--ink); }

/* footer */
.kit-rt-foot { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; padding: 6px 12px; border-top: 1px solid var(--rule-2); color: var(--ink-2); font: 12.5px/1.35 var(--f-ui); font-variant-numeric: tabular-nums; }
.kit-rt-count { margin-inline-end: auto; }
.kit-rt-ro { padding: 1px 8px; border: 1px solid var(--rule); border-radius: 999px; font-weight: 600; color: var(--ink-2); }
.kit-rt-ro[hidden], .kit-rt-limit[hidden] { display: none; }
.kit-rt-limit { display: inline-flex; align-items: center; gap: 6px; padding: 1px 8px; border-radius: 999px; font-weight: 600; }
.kit-rt-limit[data-state="near"] { background: var(--warn-soft); color: var(--ink); border: 1px dashed var(--warn); }
.kit-rt-limit[data-state="over"] { background: var(--danger-soft); color: var(--ink); border: 1px solid var(--danger); }
.kit-rt-bang { display: inline-grid; place-items: center; width: 1.25em; height: 1.25em; border-radius: 999px; background: var(--danger); color: var(--panel); font: 700 11px/1 var(--f-ui); }

/* menu, link dialog, tooltip: placed by script inside the host, above the text */
.kit-rt-menu { position: absolute; z-index: 5; min-width: 13em; margin: 0; padding: 4px; list-style: none; border: 1px solid var(--rule); border-radius: 10px; background: var(--panel); box-shadow: var(--shadow); }
.kit-rt-menu[hidden], .kit-rt-pop[hidden], .kit-rt-tip[hidden] { display: none; }
.kit-rt-mi { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 36px; padding: 4px 10px; border-radius: 7px; color: var(--ink); cursor: pointer; }
.kit-rt-mi:hover { background: var(--sunk); }
.kit-rt-mi:focus-visible, .kit-rt-mi:focus { outline: 2px solid var(--focus, var(--accent)); outline-offset: -2px; }
.kit-rt-mi[aria-checked="true"] { background: var(--accent-soft); }
.kit-rt-mi[aria-checked="true"] .kit-rt-mi-n::before { content: "✓"; display: inline-block; width: 1.2em; margin-inline-start: -1.2em; font: 700 13px/1 var(--f-ui); color: var(--accent); }
.kit-rt-mi-n { padding-inline-start: 1.2em; font: 500 14px/1.2 var(--f-ui); }
.kit-rt-mi-h2 { font: 700 17px/1.2 var(--f-display, var(--f-ui)); text-transform: var(--head-case, none); }
.kit-rt-mi-h3 { font: 650 15px/1.2 var(--f-display, var(--f-ui)); text-transform: var(--head-case, none); }
.kit-rt-mi-k { color: var(--ink-3); font: 12px/1 var(--f-mono); }
.kit-rt-pop { position: absolute; z-index: 6; display: grid; gap: 8px; width: min(22rem, calc(100% - 16px)); box-sizing: border-box; margin: 0; padding: 12px; border: 1px solid var(--rule); border-radius: 10px; background: var(--panel); box-shadow: var(--shadow); }
.kit-rt-pop-t { margin: 0; font: 700 13px/1.2 var(--f-ui); color: var(--ink); }
.kit-rt-row { display: grid; gap: 4px; }
.kit-rt-row[hidden] { display: none; }
.kit-rt-lab { font: 600 12px/1.2 var(--f-ui); color: var(--ink-2); }
.kit-rt-in { min-width: 0; min-height: 36px; padding: 6px 10px; border: 1px solid var(--rule); border-radius: 7px; background: var(--panel); color: var(--ink); font: 14px/1.3 var(--f-ui); }
.kit-rt-in:focus-visible { outline: 2px solid var(--focus, var(--accent)); outline-offset: 1px; }
.kit-rt-in[aria-invalid="true"] { border: 2px solid var(--danger); }
.kit-rt-hint { margin: 0; color: var(--ink-3); font: 12px/1.35 var(--f-ui); }
.kit-rt-err { margin: 0; color: var(--ink); font: 600 12.5px/1.35 var(--f-ui); }
.kit-rt-err:empty { display: none; }
.kit-rt-err:not(:empty)::before { content: "!"; display: inline-grid; place-items: center; width: 1.3em; height: 1.3em; margin-inline-end: 6px; border-radius: 999px; background: var(--danger); color: var(--panel); font: 700 11px/1 var(--f-ui); vertical-align: .05em; }
.kit-rt-pbtns { display: flex; flex-wrap: wrap; gap: 6px; }
.kit-rt-pb { min-height: 34px; padding: 6px 12px; border: 1px solid var(--rule); border-radius: 7px; background: var(--panel); color: var(--ink); font: 600 13px/1 var(--f-ui); cursor: pointer; }
.kit-rt-pb:hover { background: var(--sunk); }
.kit-rt-pb[hidden] { display: none; }
.kit-rt-pb:focus-visible { outline: 2px solid var(--focus, var(--accent)); outline-offset: 2px; }
.kit-rt-pri { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.kit-rt-pri:hover { background: var(--accent); filter: brightness(1.08); }
.kit-rt-tip { position: absolute; z-index: 7; max-width: 16rem; padding: 4px 8px; border-radius: 6px; background: var(--ink); color: var(--panel); font: 500 12px/1.3 var(--f-ui); white-space: nowrap; pointer-events: none; }
.kit-rt-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }

/* scrolling text area: the toolbar stays put, the text scrolls */
.kit-rt[data-scrolls] .kit-rt-ed { scrollbar-width: thin; }

@container (max-width: 480px) {
  .kit-rt-bar { padding-inline: 4px; }
  .kit-rt-blockbtn { min-width: 7.5em; }
  .kit-rt-sep { margin: 0 2px; }
  .kit-rt-foot { padding-inline: 10px; }
}
@media (pointer: coarse) {
  .kit-rt-btn { min-width: 44px; height: 44px; }
  .kit-rt-mi, .kit-rt-pb, .kit-rt-in { min-height: 44px; }
}
@media (prefers-reduced-motion: reduce) { .kit-rt-bar { scroll-behavior: auto; } }
@media print { .kit-rt-bar, .kit-rt-foot { display: none; } .kit-rt-box { border: 0; } }
/* /part:page.style.kit.rich-text */

/* part:page.script.kit.rich-text */
/**
 * Rich text editor
 * Kit.richText.mount(el, opts) draws a WYSIWYG editor: a contenteditable surface (role textbox, multi-line) under a formatting toolbar built on the WAI-ARIA toolbar pattern (one tab stop, Left and Right arrows, Home and End, mirrored in right-to-left; toggles carry aria-pressed for the selection's current state; the text style is a menu button whose menu holds menuitemradio items), a footer with word and character counts, and a link popover (a non-modal dialog, never window.prompt). It returns {get(), value(), getHTML(), getText(), getMarkdown(), setHTML(html), insertHTML(html), exec(command, arg), state(), focus(), update(patch), destroy()}.
 *
 * Formatting: bold, italic, underline, strikethrough, inline code, links (http, https and mailto only; javascript: and every other scheme is refused in words), paragraph, heading 2 and heading 3, bulleted and numbered lists (Tab and Shift+Tab indent and outdent inside a list; outside a list Tab moves focus as usual, and after Escape the next Tab always leaves), block quote, code block, horizontal rule, undo, redo and clear formatting (marks off, headings and code blocks back to paragraphs; links kept). Every shortcut is in the button's tooltip and in aria-keyshortcuts, written for the platform (⌘B on a Mac, Ctrl+B elsewhere). Alt+F10 moves focus from the text to the toolbar and Escape moves it back.
 * Typing rules: "# " or "## " starts a heading 2, "### " a heading 3, "- ", "* " or "+ " a bulleted list, "1. " a numbered list, "> " a quote, ``` a code block, --- a rule; **bold**, __bold__, *italic*, _italic_, `code` and ~~strike~~ format as they close. Each one is announced and undone by one Ctrl+Z, which leaves the characters as typed.
 * Paste and drop are cleaned by an allow-list walk written here (DOMParser, nothing from a CDN): p, h2, h3, strong, em, u, s, code, pre, blockquote, ul, ol, li, a[href], hr, br, and img[src, alt] only with allowImages. Styles, classes, ids, event handlers, scripts, frames, forms and unsafe links go; bold, italic, underline and strike written as inline styles (word processors, office suites) are kept as marks, h1 becomes h2 and h4 to h6 become h3. Ctrl+Shift+V pastes plain text; a web address pasted over selected text links it. Copy and cut put the same clean HTML and plain text on the clipboard.
 *
 * Commands work on the DOM Range and Selection directly; document.execCommand is not used at all. Undo is the editor's own stack of snapshots (HTML and a caret offset), with typing grouped by word and pause, so every command, paste and typing rule undoes in one step; the browser's own history inputs (historyUndo, historyRedo, from menus or a shake) are routed to the same stack. Enter, Shift+Enter, Backspace at the start of a block and Delete at the end are handled by the editor (beforeinput), so lists, quotes, headings and code blocks split and join the same way everywhere. Each block carries dir="auto" while editing (code blocks dir="ltr"), so Arabic and Hebrew lines run right to left beside English ones; the HTML out has no dir attributes.
 *
 * API:
 *   Kit.richText.mount(el, opts) -> handle
 *     opts.value        starting HTML (cleaned on the way in)
 *     opts.placeholder  text shown while the editor is empty (also aria-placeholder)
 *     opts.label        accessible name of the text area (default "Rich text editor")
 *     opts.readOnly     true: no toolbar, the text can still be selected, copied and reached with Tab
 *     opts.toolbar      ids in order, '|' for a separator, false for none: block bold italic underline strike code link bulletList orderedList outdent indent quote codeBlock rule undo redo clear
 *     opts.maxLength    a soft limit in characters: the footer counts down, then states "n over the limit" with a ! mark and a border, and announces crossing it
 *     opts.minHeight, opts.maxHeight   numbers (px) or CSS lengths: the text area grows to maxHeight, then scrolls
